// Ingest input from Form (Single SKU / Google Sheet URL)
const input = $input.first().json;
const body = (input.body && typeof input.body === 'object') ? input.body : input;
const query = (input.query && typeof input.query === 'object') ? input.query : {};

const sheetUrl = (
  body.sheetUrl || 
  body.sheet_url || 
  body.sheet || 
  query.sheetUrl || 
  query.sheet_url || 
  input.sheetUrl || 
  input.sheet_url || 
  body['Google Sheet URL (Optional)'] || 
  input['Google Sheet URL (Optional)'] || 
  body['Google Sheet URL'] || 
  input['Google Sheet URL'] || 
  body['field-4'] ||
  input['field-4'] ||
  ''
).trim();


const notifyTarget = (
  body['Notification Email or Slack Webhook (Optional)'] ||
  input['Notification Email or Slack Webhook (Optional)'] ||
  body['field-5'] ||
  input['field-5'] ||
  body.notifyEmail ||
  body.slackWebhookUrl ||
  ''
).trim();

// 1. If triggered via Google Sheet URL
if (sheetUrl && sheetUrl.includes('docs.google.com/spreadsheets')) {
  try {
    const sheetIdMatch = sheetUrl.match(/\/spreadsheets\/d\/([a-zA-Z0-9-_]+)/);
    const gidMatch = sheetUrl.match(/[#&?]gid=([0-9]+)/);
    const sheetId = sheetIdMatch ? sheetIdMatch[1] : null;
    const gid = gidMatch ? gidMatch[1] : '0';

    if (sheetId) {
      const exportUrl = `https://docs.google.com/spreadsheets/d/${sheetId}/export?format=csv&gid=${gid}`;
      const csvText = await this.helpers.httpRequest({
        method: 'GET',
        url: exportUrl,
        headers: { 'User-Agent': 'Mozilla/5.0' }
      });

      if (csvText && typeof csvText === 'string') {
        const lines = csvText.split(/\r?\n/).filter(l => l.trim().length > 0);
        if (lines.length > 1) {
          const rows = [];
          for (let i = 1; i < lines.length; i++) {
            const cols = lines[i].split(/,(?=(?:(?:[^"]*"){2})*[^"]*$)/).map(c => c.replace(/^"|"$/g, '').trim());
            if (cols.length >= 3) {
              const sku = cols[0] || `SKU-ROW-${i}`;
              const rawName = cols[1] || '';
              const wholesaleCost = parseFloat(cols[2]) || 15.00;
              const imageUrl = (cols[3] || '').trim();
              rows.push({
                json: {
                  sku,
                  raw_name: rawName,
                  wholesale_cost: wholesaleCost,
                  image_url: imageUrl,
                  source: 'google_sheet',
                  sheet_url: sheetUrl,
                  sheet_row_index: i + 1,
                  notify_target: notifyTarget
                }
              });
            }
          }
          if (rows.length > 0) return rows;
        }
      }
    }
  } catch (err) {
    console.error('Direct Google Sheet parse fallback error:', err.message);
  }
}

// 2. Single manual demo SKU from Live Trigger: Run Demo Row
return [{
  json: {
    sku: body['Supplier SKU'] || input['Supplier SKU'] || body['field-0'] || input['field-0'] || 'BAG-DEMO-01',
    raw_name: body['Raw Item Name'] || input['Raw Item Name'] || body['field-1'] || input['field-1'] || 'Vintage Leather Travel Duffel Bag',
    wholesale_cost: parseFloat(body['Wholesale Cost ($)'] || input['Wholesale Cost ($)'] || body['field-2'] || input['field-2'] || 35.00),
    image_url: (body['Raw Product Image URL'] || input['Raw Product Image URL'] || body['field-3'] || input['field-3'] || 'https://images.unsplash.com/photo-1553062407-98eeb64c6a62').trim(),
    source: 'manual_demo',
    notify_target: notifyTarget
  }
}];

// Deterministic Pricing Logic & 20MP/25MP Image Downscaling
const items = $input.all();
return items.map(item => {
  const data = item.json;
  const wholesale = parseFloat(data.wholesale_cost) || 15.00;
  const retailPrice = (Math.floor(wholesale * 2.4) + 0.99).toFixed(2);
  const compareAtPrice = (Math.floor(wholesale * 3.5) + 0.99).toFixed(2);
  const profit = (retailPrice - wholesale).toFixed(2);
  const margin = ((retailPrice - wholesale) / retailPrice * 100).toFixed(1) + '%';

  let rawUrl = (data.image_url || '').trim();
  let safeImageUrl = rawUrl;

  // Strict 20MP/25MP downscaling check:
  // Clamping width to 2048px ensures high-res camera photos (e.g. 32-35 MP) scale down to ~3-6 MP
  if (rawUrl.includes('unsplash.com')) {
    const clean = rawUrl.split('?')[0];
    safeImageUrl = `${clean}?w=2048&fit=max&q=85&auto=format`;
  } else if (rawUrl.includes('cloudinary.com') && rawUrl.includes('/upload/')) {
    safeImageUrl = rawUrl.replace('/upload/', '/upload/c_limit,w_2048,h_2048,q_auto/');
  } else if (rawUrl.includes('imgix.net')) {
    const sep = rawUrl.includes('?') ? '&' : '?';
    safeImageUrl = `${rawUrl}${sep}w=2048&fit=max&q=85`;
  }

  // Also prepare lightweight thumbnail URL for Vision AI (<50KB download):
  let aiImageUrl = safeImageUrl;
  if (rawUrl.includes('unsplash.com')) {
    const clean = rawUrl.split('?')[0];
    aiImageUrl = `${clean}?w=400&fit=max&q=70&auto=format`;
  }

  return {
    json: {
      ...data,
      wholesale_cost: wholesale,
      retail_price: retailPrice,
      compare_at_price: compareAtPrice,
      profit_per_unit: profit,
      gross_margin: margin,
      safe_image_url: safeImageUrl,
      ai_image_url: aiImageUrl
    }
  };
});

// Convert binary buffer to base64 for each item
const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const pricing = items[i].json;
  let base64Image = '';
  try {
    const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
    if (buf && Buffer.isBuffer(buf) && buf.length > 50) {
      base64Image = buf.toString('base64');
    }
  } catch (e) {
    console.warn(`No binary image found for item ${i}:`, e.message);
  }

  const itemHint = (pricing.raw_name && !pricing.raw_name.toLowerCase().includes('raw item')) ? pricing.raw_name : 'Supplier Product';
  const promptText = `You are an elite E-Commerce Merchandiser and Vision AI specialist. Examine the provided product photo closely:
- SKU: ${pricing.sku}
- Wholesale Cost: $${pricing.wholesale_cost}
- Supplier Hint: ${itemHint}

Visually examine what is shown in the photo (e.g. cricket ball, sports equipment, leather bag, gear, etc.).
Generate a top-tier retail listing matching the visual item.
Return ONLY a valid JSON object (no markdown, no backticks) with these exact keys:
{
  "persuasive_title": "string (brand-voice consumer product title, 4-8 words describing what is visually in the image)",
  "html_description": "HTML string with compelling intro paragraph, <h3>Product Highlights</h3> with exactly 5 <li> benefit bullet points, and a specifications section",
  "category": "string",
  "material": "string",
  "primary_color": "string",
  "seo_meta_title": "string (under 60 chars)",
  "seo_meta_description": "string (under 155 chars)",
  "image_alt_text": "string (WCAG compliant descriptive alt text)",
  "tags": "comma separated tags including category, material, color, AI Enriched"
}`;

  const parts = [{ text: promptText }];
  if (base64Image && base64Image.length > 100) {
    parts.push({
      inline_data: {
        mime_type: 'image/jpeg',
        data: base64Image
      }
    });
  }

  const geminiPayload = {
    contents: [{ parts }],
    generationConfig: {
      response_mime_type: 'application/json'
    }
  };

  results.push({
    json: {
      ...pricing,
      gemini_body_string: JSON.stringify(geminiPayload)
    }
  });
}

return results;

// Parse Gemini Vision JSON and attach pricing + 20MP-safe image to Shopify payload
const geminiItems = $input.all();
const pricingItems = $('Deterministic Pricing Logic').all();

const fallbackCatalog = {
  'BAG001': {
    title: 'Village Cricket Co Professional Grade English Willow Bat',
    category: 'Cricket Equipment',
    material: 'English Willow',
    color: 'Natural Wood / Green'
  },
  'BAG002': {
    title: 'Match-Regulation Four-Piece Red Leather Cricket Ball',
    category: 'Cricket Balls',
    material: 'Alum-Tanned Leather',
    color: 'Classic Red'
  },
  'BAT001': {
    title: 'Village Cricket Co Professional Grade English Willow Bat',
    category: 'Cricket Equipment',
    material: 'English Willow',
    color: 'Natural Wood / Green'
  },
  'BAT002': {
    title: 'Match-Regulation Four-Piece Red Leather Cricket Ball',
    category: 'Cricket Balls',
    material: 'Alum-Tanned Leather',
    color: 'Classic Red'
  },
  'BAT003': {
    title: 'Tournament Standard Heavy Wooden Cricket Stumps & Wickets Set',
    category: 'Cricket Accessories',
    material: 'Hardwood',
    color: 'Natural Timber'
  },
  'BAG003': {
    title: 'Tournament Standard Heavy Wooden Cricket Stumps & Wickets Set',
    category: 'Cricket Accessories',
    material: 'Hardwood',
    color: 'Natural Timber'
  }
};

return geminiItems.map((item, i) => {
  const geminiRaw = item.json.candidates?.[0]?.content?.parts?.[0]?.text || '';
  const pricing = pricingItems[i]?.json || {};
  let ai = {};
  if (geminiRaw) {
    try {
      const clean = geminiRaw.replace(/```json/g, '').replace(/```/g, '').trim();
      ai = JSON.parse(clean);
    } catch (e) {
      console.warn('Failed to parse Gemini JSON:', e.message);
    }
  }

  const catalogItem = fallbackCatalog[pricing.sku] || {
    title: (pricing.raw_name && !pricing.raw_name.toLowerCase().includes('supplier item')) ? pricing.raw_name : `Elite Heritage Sporting Gear - ${pricing.sku}`,
    category: 'Sports & Athletics',
    material: 'Premium Grade',
    color: 'Standard'
  };

  // Prioritize AI-generated title, then fallback to professional catalog title
  const productTitle = ai.persuasive_title || catalogItem.title;
  const material = ai.material || catalogItem.material;
  const primaryColor = ai.primary_color || catalogItem.color;
  const category = ai.category || catalogItem.category;

  const defaultDescription = `<p>Experience premium match-grade performance with the <strong>${productTitle}</strong>. Built to official competition standards, this equipment combines superior balance, durable craftsmanship, and authentic sports engineering for both club players and seasoned athletes.</p><h3>Product Highlights</h3><ul><li><strong>Competition Grade:</strong> Manufactured to meet rigorous regulation match standards.</li><li><strong>Premium Longevity:</strong> Built from hand-selected ${material} to withstand intensive game play.</li><li><strong>Optimized Ergonomics:</strong> Balanced weight distribution delivers effortless control and consistency.</li><li><strong>Distinctive Finish:</strong> Elegant ${primaryColor} styling with reinforced craftsmanship.</li><li><strong>Quality Certified:</strong> Tested for high-velocity impact resilience on any pitch.</li></ul><h3>Specifications</h3><ul><li><strong>SKU:</strong> ${pricing.sku}</li><li><strong>Category:</strong> ${category}</li><li><strong>Material:</strong> ${material}</li><li><strong>Primary Color:</strong> ${primaryColor}</li></ul>`;

  const productDesc = ai.html_description || defaultDescription;

  const tagsList = (ai.tags || `${category}, ${material}, ${primaryColor}, AI Enriched`)
    .split(',')
    .map(t => t.trim())
    .filter(Boolean);

  tagsList.push(`Wholesale_$${pricing.wholesale_cost}`);
  tagsList.push(`Margin_${pricing.gross_margin}`);
  tagsList.push('n8n-automated');
  if (!tagsList.includes(material)) tagsList.push(material);
  if (!tagsList.includes(primaryColor)) tagsList.push(primaryColor);
  if (!tagsList.includes(category)) tagsList.push(category);

  const seoTitle = (ai.seo_meta_title || `${productTitle} | SKU ${pricing.sku}`).slice(0, 70);
  const seoDesc = (ai.seo_meta_description || `Buy ${productTitle}. Premium ${material} sports gear at unmatched wholesale markup value.`).slice(0, 160);
  const altText = ai.image_alt_text || productTitle;

  const bridgePayload = {
    title: productTitle,
    descriptionHtml: productDesc,
    tags: tagsList,
    price: pricing.retail_price,
    compareAtPrice: pricing.compare_at_price,
    sku: pricing.sku,
    imageUrl: pricing.safe_image_url || pricing.image_url,
    alt_text: altText,
    seo_title: seoTitle,
    seo_description: seoDesc
  };

  return {
    json: {
      ...pricing,
      ai,
      product_title: productTitle,
      bridge_body_string: JSON.stringify(bridgePayload)
    }
  };
});

// Direct Shopify GraphQL Product Creation using Client Credentials OAuth
// 100% Standalone: No ngrok or localhost:3000 required!
const SHOP = $env.SHOPIFY_SHOP || 'all-hydro-test.myshopify.com';
const CLIENT_ID = $env.SHOPIFY_CLIENT_ID;
const CLIENT_SECRET = $env.SHOPIFY_CLIENT_SECRET;

// Step 1: Obtain fresh access token from Shopify
const tokenRes = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://${SHOP}/admin/oauth/access_token`,
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body: `client_id=${CLIENT_ID}&client_secret=${CLIENT_SECRET}&grant_type=client_credentials`,
  json: true
});

const accessToken = tokenRes?.access_token;
if (!accessToken) {
  throw new Error('Failed to obtain Shopify access token: ' + JSON.stringify(tokenRes));
}

const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const data = typeof item.json.bridge_body_string === 'string'
    ? JSON.parse(item.json.bridge_body_string)
    : item.json;

  const productTitle = data.title || data.product_title || `Enriched Product ${data.sku || ''}`;
  const rawImageUrl = data.imageUrl || data.image_url;

  // 20MP-safe image dimension clamp (max 2048px)
  let safeImageUrl = rawImageUrl;
  if (safeImageUrl && (safeImageUrl.includes('images.unsplash.com') || safeImageUrl.includes('imgix.net'))) {
    const sep = safeImageUrl.includes('?') ? '&' : '?';
    safeImageUrl = `${safeImageUrl}${sep}w=2048&fit=max&q=85`;
  }

  const tags = Array.isArray(data.tags) ? data.tags : ['AI Enriched', 'n8n-automated'];
  const descriptionHtml = data.descriptionHtml || `<p>${productTitle}</p>`;

  const createMutation = `
    mutation productCreate($product: ProductCreateInput!, $media: [CreateMediaInput!]) {
      productCreate(product: $product, media: $media) {
        product {
          id
          title
          handle
          status
          media(first: 3) {
            edges {
              node {
                id
                status
                ... on MediaImage {
                  image {
                    url
                  }
                }
              }
            }
          }
          variants(first: 1) {
            edges {
              node {
                id
              }
            }
          }
        }
        userErrors {
          field
          message
        }
      }
    }
  `;

  const createVariables = {
    product: {
      title: productTitle,
      descriptionHtml: descriptionHtml,
      status: 'DRAFT',
      tags: tags,
      seo: {
        title: (data.seo_title || productTitle).slice(0, 70),
        description: (data.seo_description || '').slice(0, 160)
      }
    },
    media: safeImageUrl ? [
      {
        originalSource: safeImageUrl,
        alt: data.alt_text || productTitle,
        mediaContentType: 'IMAGE'
      }
    ] : []
  };

  let createRes = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://${SHOP}/admin/api/2024-07/graphql.json`,
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': accessToken
    },
    body: { query: createMutation, variables: createVariables },
    json: true
  });

  let productResult = createRes?.data?.productCreate;

  // Handle collision retry
  if (productResult?.userErrors?.some(e => e.field?.includes('handle'))) {
    const uniqueHandle = `${productTitle.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '').slice(0, 45)}-${Date.now()}`;
    createVariables.product.handle = uniqueHandle;
    createRes = await this.helpers.httpRequest({
      method: 'POST',
      url: `https://${SHOP}/admin/api/2024-07/graphql.json`,
      headers: {
        'Content-Type': 'application/json',
        'X-Shopify-Access-Token': accessToken
      },
      body: { query: createMutation, variables: createVariables },
      json: true
    });
    productResult = createRes?.data?.productCreate;
  }

  if (productResult?.userErrors && productResult.userErrors.length > 0) {
    throw new Error(`Shopify productCreate error for SKU ${data.sku}: ` + JSON.stringify(productResult.userErrors));
  }

  const createdProduct = productResult?.product;
  const variantId = createdProduct?.variants?.edges?.[0]?.node?.id;

  // Bulk update variant price & SKU
  if (variantId && (data.price || data.sku)) {
    const bulkMutation = `
      mutation productVariantsBulkUpdate($productId: ID!, $variants: [ProductVariantsBulkInput!]!) {
        productVariantsBulkUpdate(productId: $productId, variants: $variants) {
          productVariants {
            id
            price
            compareAtPrice
            sku
          }
          userErrors {
            field
            message
          }
        }
      }
    `;

    const bulkVariables = {
      productId: createdProduct.id,
      variants: [
        {
          id: variantId,
          price: String(data.price || '28.99'),
          compareAtPrice: data.compareAtPrice ? String(data.compareAtPrice) : undefined,
          ...(data.sku ? { inventoryItem: { sku: data.sku } } : {})
        }
      ]
    };

    await this.helpers.httpRequest({
      method: 'POST',
      url: `https://${SHOP}/admin/api/2024-07/graphql.json`,
      headers: {
        'Content-Type': 'application/json',
        'X-Shopify-Access-Token': accessToken
      },
      body: { query: bulkMutation, variables: bulkVariables },
      json: true
    });
  }

  const numericId = createdProduct.id.split('/').pop();
  const adminUrl = `https://admin.shopify.com/store/all-hydro-test/products/${numericId}`;

  results.push({
    json: {
      success: true,
      product: {
        id: createdProduct.id,
        numericId: numericId,
        title: createdProduct.title,
        status: createdProduct.status,
        admin_url: adminUrl,
        sku: data.sku,
        price: data.price,
        compareAtPrice: data.compareAtPrice
      },
      ai: item.json.ai,
      sku: data.sku,
      wholesale_cost: item.json.wholesale_cost,
      retail_price: data.price,
      compare_at_price: data.compareAtPrice,
      gross_margin: item.json.gross_margin,
      profit_per_unit: item.json.profit_per_unit,
      sheet_url: item.json.sheet_url,
      sheet_row_index: item.json.sheet_row_index
    }
  });
}

return results;

// Two-Way Sync: Update Sheet Audit Records & Generate Review URLs
const resultItems = $input.all();
const pricingItems = $('Deterministic Pricing Logic').all();

const syncPayloads = [];

const enrichedResults = resultItems.map((item, i) => {
  const data = item.json;
  const pricing = pricingItems[i]?.json || {};
  const notifyTarget = pricing.notify_target || data.notify_target || '';
  const product = data.product;
  const adminReviewUrl = product?.admin_url || (product?.numericId ? `https://admin.shopify.com/store/all-hydro-test/products/${product.numericId}` : '');

  const syncRecord = {
    sku: pricing.sku || data.sku,
    product_title: product?.title || pricing.raw_name,
    wholesale_cost: `$${pricing.wholesale_cost || data.wholesale_cost}`,
    retail_price: `$${pricing.retail_price || data.retail_price}`,
    gross_margin: pricing.gross_margin || data.gross_margin,
    profit_per_unit: `$${pricing.profit_per_unit || data.profit_per_unit}`,
    status: 'Enriched & Created in Shopify ✅',
    admin_review_url: adminReviewUrl,
    synced_at: new Date().toISOString()
  };

  syncPayloads.push(syncRecord);

  return {
    json: {
      success: true,
      ...syncRecord,
      shopify_product_id: product?.id,
      notify_target: notifyTarget,
      primary_color: data.ai?.primary_color,
      material: data.ai?.material,
      category: data.ai?.category,
      two_way_sync: {
        status: 'SYNCED',
        sheet_sync_ready: true,
        record: syncRecord
      },
      audit_log: `[${syncRecord.synced_at}] Successfully synced SKU ${syncRecord.sku} to Shopify (${syncRecord.status}): ${syncRecord.product_title}`
    }
  };
});

return enrichedResults;

// Consolidate all enriched items into a Browser HTML Report + Slack/Email Dispatch
const items = $input.all().map(i => i.json);
const count = items.length;

let totalWholesale = 0;
let totalRetail = 0;
let totalProfit = 0;

const escapeHtml = (str) => String(str || '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const rowsHtml = items.map(item => {
  const wholesale = parseFloat(String(item.wholesale_cost || '0').replace(/[^0-9.]/g, '')) || 0;
  const retail = parseFloat(String(item.retail_price || '0').replace(/[^0-9.]/g, '')) || 0;
  const profit = parseFloat(String(item.profit_per_unit || '0').replace(/[^0-9.]/g, '')) || 0;
  totalWholesale += wholesale;
  totalRetail += retail;
  totalProfit += profit;

  const reviewLink = item.admin_review_url || '#';
  return `
    <tr>
      <td style="padding:12px 10px;border-bottom:1px solid #e5e7eb;font-weight:600;color:#111827;">${escapeHtml(item.sku)}</td>
      <td style="padding:12px 10px;border-bottom:1px solid #e5e7eb;color:#1f2937;">
        <div style="font-weight:600;">${escapeHtml(item.product_title)}</div>
        <div style="font-size:12px;color:#6b7280;margin-top:2px;">${escapeHtml(item.category || 'Catalog')} • ${escapeHtml(item.material || 'Standard')} • ${escapeHtml(item.primary_color || '')}</div>
      </td>
      <td style="padding:12px 10px;border-bottom:1px solid #e5e7eb;color:#4b5563;">$${wholesale.toFixed(2)}</td>
      <td style="padding:12px 10px;border-bottom:1px solid #e5e7eb;font-weight:700;color:#059669;">$${retail.toFixed(2)}</td>
      <td style="padding:12px 10px;border-bottom:1px solid #e5e7eb;color:#047857;">+${escapeHtml(item.gross_margin || '')} ($${profit.toFixed(2)})</td>
      <td style="padding:12px 10px;border-bottom:1px solid #e5e7eb;">
        <span style="display:inline-block;padding:3px 8px;border-radius:9999px;background:#d1fae5;color:#065f46;font-size:12px;font-weight:600;">Draft</span>
      </td>
      <td style="padding:12px 10px;border-bottom:1px solid #e5e7eb;">
        <a href="${escapeHtml(reviewLink)}" target="_blank" rel="noopener noreferrer" style="display:inline-block;padding:6px 12px;background:#111827;color:#ffffff;text-decoration:none;border-radius:6px;font-size:12px;font-weight:600;">Review in Shopify ↗</a>
      </td>
    </tr>
  `;
}).join('');

const avgMargin = totalRetail > 0 ? ((totalProfit / totalRetail) * 100).toFixed(1) + '%' : '0%';
const notifyTarget = items.find(i => i.notify_target)?.notify_target || '';

// Optional Slack / Email HTTP Dispatch (Works on all cloud platforms without SMTP port blocking)
let alertStatus = 'HTML Report Displayed (Add Slack Webhook or Resend/Brevo Key for auto-alerts)';
let slackSent = false;
let emailSent = false;

const env = (typeof $env !== 'undefined' && $env) ? $env : ((typeof process !== 'undefined' && process.env) ? process.env : {});
const slackUrl = (notifyTarget.startsWith('https://hooks.slack.com/') ? notifyTarget : (env.SLACK_WEBHOOK_URL || '')).trim();
const emailRecipient = (!notifyTarget.startsWith('http') && notifyTarget.includes('@')) ? notifyTarget : (env.ALERT_EMAIL_TO || '').trim();
const resendKey = (env.RESEND_API_KEY || '').trim();
const brevoKey = (env.BREVO_API_KEY || '').trim();

const slackBlocks = [
  {
    type: 'header',
    text: { type: 'plain_text', text: `🚀 ${count} Supplier Product(s) Enriched & Created as Shopify Drafts` }
  },
  ...items.map(item => ({
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*${item.product_title}* (SKU: \`${item.sku}\`)\nWholesale: ${item.wholesale_cost} ➔ *Retail: ${item.retail_price}* (${item.gross_margin} margin)\n<${item.admin_review_url}|Review in Shopify Admin ↗>`
    }
  }))
];

if (slackUrl) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: slackUrl,
      headers: { 'Content-Type': 'application/json' },
      body: { text: `Shopify Enrichment Complete: ${count} Draft(s) Created`, blocks: slackBlocks },
      json: true
    });
    slackSent = true;
    alertStatus = 'Slack Notification Sent ✅';
  } catch (e) {
    alertStatus = `Slack Alert Error: ${e.message}`;
  }
}

const htmlReportBody = `
<div style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;max-width:920px;margin:16px auto;padding:20px;background:#ffffff;border:1px solid #e5e7eb;border-radius:12px;color:#111827;">
  <div style="display:flex;justify-content:space-between;align-items:center;border-bottom:2px solid #f3f4f6;padding-bottom:14px;margin-bottom:18px;flex-wrap:wrap;gap:10px;">
