      <h2 style="margin:0;font-size:20px;color:#111827;">✅ Supplier-to-Shopify Enrichment Report</h2>
      <p style="margin:4px 0 0;font-size:13px;color:#6b7280;">Automated Vision AI + 2.4x Pricing + Direct Shopify GraphQL Draft Sync</p>
    </div>
    <span style="padding:6px 12px;background:#ecfdf5;border:1px solid #a7f3d0;color:#065f46;border-radius:8px;font-size:12px;font-weight:600;">${escapeHtml(alertStatus)}</span>
  </div>

  <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;margin-bottom:20px;">
    <div style="background:#f9fafb;padding:12px 14px;border-radius:8px;border:1px solid #e5e7eb;">
      <div style="font-size:11px;text-transform:uppercase;color:#6b7280;font-weight:600;">Drafts Created</div>
      <div style="font-size:22px;font-weight:700;color:#111827;margin-top:4px;">${count}</div>
    </div>
    <div style="background:#f9fafb;padding:12px 14px;border-radius:8px;border:1px solid #e5e7eb;">
      <div style="font-size:11px;text-transform:uppercase;color:#6b7280;font-weight:600;">Total Retail Value</div>
      <div style="font-size:22px;font-weight:700;color:#059669;margin-top:4px;">$${totalRetail.toFixed(2)}</div>
    </div>
    <div style="background:#f9fafb;padding:12px 14px;border-radius:8px;border:1px solid #e5e7eb;">
      <div style="font-size:11px;text-transform:uppercase;color:#6b7280;font-weight:600;">Projected Profit</div>
      <div style="font-size:22px;font-weight:700;color:#047857;margin-top:4px;">$${totalProfit.toFixed(2)}</div>
    </div>
    <div style="background:#f9fafb;padding:12px 14px;border-radius:8px;border:1px solid #e5e7eb;">
      <div style="font-size:11px;text-transform:uppercase;color:#6b7280;font-weight:600;">Avg Gross Margin</div>
      <div style="font-size:22px;font-weight:700;color:#1d4ed8;margin-top:4px;">${avgMargin}</div>
