  </div>
</div>
`;

if (emailRecipient && resendKey) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.resend.com/emails',
      headers: {
        'Authorization': `Bearer ${resendKey}`,
        'Content-Type': 'application/json'
      },
      body: {
        from: env.ALERT_EMAIL_FROM || 'Shopify Pipeline <onboarding@resend.dev>',
        to: [emailRecipient],
        subject: `✅ ${count} Shopify Draft Product(s) Enriched & Ready for Review`,
        html: htmlReportBody
      },
      json: true
    });
    emailSent = true;
    alertStatus = slackSent ? 'Slack & Email Sent ✅' : `Email Sent to ${emailRecipient} ✅`;
  } catch (e) {
    alertStatus += ` | Resend Error: ${e.message}`;
  }
} else if (emailRecipient && brevoKey) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.brevo.com/v3/smtp/email',
      headers: {
        'api-key': brevoKey,
        'Content-Type': 'application/json'
      },
      body: {
        sender: { name: 'Shopify Pipeline', email: env.ALERT_EMAIL_FROM || 'noreply@example.com' },
        to: [{ email: emailRecipient }],
        subject: `✅ ${count} Shopify Draft Product(s) Enriched & Ready for Review`,
        htmlContent: htmlReportBody
      },
      json: true
    });
    emailSent = true;
    alertStatus = slackSent ? 'Slack & Email Sent ✅' : `Email Sent to ${emailRecipient} ✅`;
  } catch (e) {
    alertStatus += ` | Brevo Error: ${e.message}`;
  }
}

return [{
  json: {
    success: true,
    count,
    total_retail_value: `$${totalRetail.toFixed(2)}`,
    total_profit: `$${totalProfit.toFixed(2)}`,
    avg_gross_margin: avgMargin,
    slack_sent: slackSent,
    email_sent: emailSent,
    alert_status: alertStatus,
    notify_target: notifyTarget,
    html_report: htmlReportBody,
    email_subject: `✅ ${count} Shopify Draft Product(s) Enriched & Ready for Review`,
    slack_blocks: slackBlocks,
    items
  }
}];
